package app.tonal.android;

import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.os.Handler;
import android.os.Looper;
import android.os.Process;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.json.JSONArray;
import org.json.JSONObject;

/**
 * Baked garland images shared by every Christmas surface, generated by
 * packaging/generate-christmas-assets.py. They decode once, off the main thread and
 * below normal priority, and only for the Christmas theme.
 */
final class ChristmasAssets {
    static final String[] COLORS={"red","gold","green","blue"};
    static final class Bulb {final float x,y,angle;final int color;final boolean front;Bulb(float x,float y,float angle,int color,boolean front){this.x=x;this.y=y;this.angle=angle;this.color=color;this.front=front;}}

    final Bitmap front,back,lit,wire,socket,star,glow;final Bitmap[] on=new Bitmap[4],off=new Bitmap[4];final Bulb[] bulbs;final float margin,length,span;
    private static volatile ChristmasAssets shared;
    private static boolean loading;
    private static final List<Runnable> waiting=new ArrayList<>();
    private static final Handler main=new Handler(Looper.getMainLooper());

    private ChristmasAssets(Context context)throws Exception{
        front=image(context,"garland_front");back=image(context,"garland_back");lit=image(context,"garland_lit");wire=image(context,"wire");socket=image(context,"socket");star=image(context,"star");glow=image(context,"star_glow");
        for(int i=0;i<4;i++){on[i]=image(context,"bulb_"+COLORS[i]);off[i]=image(context,"bulb_"+COLORS[i]+"_off");}
        byte[] text;try(InputStream in=context.getAssets().open("seasonal/garland.json")){text=in.readAllBytes();}
        JSONObject meta=new JSONObject(new String(text,StandardCharsets.UTF_8));margin=(float)meta.getDouble("margin");length=(float)meta.getDouble("bulbLength");span=(float)meta.getDouble("spriteSpan");
        JSONArray rows=meta.getJSONArray("bulbs");bulbs=new Bulb[rows.length()];
        for(int i=0;i<bulbs.length;i++){JSONObject b=rows.getJSONObject(i);int color=0;for(int c=0;c<4;c++)if(COLORS[c].equals(b.getString("color")))color=c;bulbs[i]=new Bulb((float)b.getDouble("x"),(float)b.getDouble("y"),(float)b.getDouble("angle"),color,"front".equals(b.getString("layer")));}
    }
    private static Bitmap image(Context context,String name)throws Exception{try(InputStream in=context.getAssets().open("seasonal/"+name+".webp")){Bitmap bitmap=BitmapFactory.decodeStream(in);if(bitmap==null)throw new IllegalStateException(name);return bitmap;}}

    /** Ready images, or null while they load; ready then runs on the main thread. */
    static ChristmasAssets get(Context context,Runnable ready){
        ChristmasAssets current=shared;if(current!=null)return current;
        synchronized(waiting){
            if(ready!=null)waiting.add(ready);if(loading)return null;loading=true;
        }
        Context app=context.getApplicationContext();
        Thread worker=new Thread(()->{
            Process.setThreadPriority(Process.THREAD_PRIORITY_BACKGROUND);
            try{shared=new ChristmasAssets(app);}catch(Exception|OutOfMemoryError error){Diagnostics.write("Natal: imagens indisponíveis");}
            main.post(()->{List<Runnable> calls;synchronized(waiting){loading=false;calls=new ArrayList<>(waiting);waiting.clear();}if(shared!=null)for(Runnable call:calls)call.run();});
        },"TonalChristmasAssets");worker.start();return null;
    }
    /** Leaving the theme gives the bitmaps back. */
    static void release(){shared=null;}
}
